// Owns the Unicode rules of a source's logical name (IMPL 20.1) over the pinned Unicode 15.0.0 data (UnicodeNameData, generated by
// GenerateNameUnicode.ps1): simple case folding, CaseFolding.txt's C and S mappings, never full folding (ß and ss differ).
// Input: names as UTF-16 text. Output: a comparer under simple case folding. A lone surrogate stays its own code unit, never
// folded or replaced, so names that differ only in invalid UTF-16 stay distinct. No allocation; no host culture or ICU data.

using System.Buffers;
using System.Text;

namespace Kimi.Compiler.Helper;

internal static class UnicodeNameHelper
{
    /// <summary>Gets the comparer of names under simple case folding (IMPL 20.1).</summary>
    internal static IEqualityComparer<string> SimpleCaseFolding { get; } = new Folding();

    /// <summary>Gets a scalar's simple case folding, or the scalar itself when it has none.</summary>
    /// <param name="scalar">The scalar value.</param>
    /// <returns>The folded scalar.</returns>
    internal static int Fold(int scalar)
    {
        var data = UnicodeNameData.SimpleCaseFolding;
        var low = 0;
        var high = (data.Length / 2) - 1;
        while (low <= high)
        {
            var middle = (low + high) >> 1;
            var key = data[middle * 2];
            if (scalar < key)
            {
                high = middle - 1;
            }
            else if (scalar > key)
            {
                low = middle + 1;
            }
            else
            {
                return data[(middle * 2) + 1];
            }
        }

        return scalar;
    }

    // The next folded scalar of a name, or a lone surrogate's own code unit.
    private static int Next(string name, ref int index)
    {
        if (Rune.DecodeFromUtf16(name.AsSpan(index), out var rune, out var count) != OperationStatus.Done)
        {
            return name[index++];
        }

        index += count;
        return Fold(rune.Value);
    }

    private sealed class Folding : IEqualityComparer<string>
    {
        public bool Equals(string? x, string? y)
        {
            if (x is null || y is null)
            {
                return ReferenceEquals(x, y);
            }

            int i = 0, j = 0;
            while (i < x.Length && j < y.Length)
            {
                if (Next(x, ref i) != Next(y, ref j))
                {
                    return false;
                }
            }

            return i == x.Length && j == y.Length;
        }

        public int GetHashCode(string name)
        {
            var hash = default(HashCode);
            for (var i = 0; i < name.Length;)
            {
                hash.Add(Next(name, ref i));
            }

            return hash.ToHashCode();
        }
    }
}
